36		}
37		if delim, ok := open.(json.Delim); !ok || delim != '{' {
38			return nil, fmt.Errorf("decode labels: must be an object of string values")
39		}
40		labels := make(map[string]string)
41		for dec.More() {
42			keyToken, err := dec.Token()
43			if err != nil {
