49			}
50			if _, dup := labels[key]; dup {
51				return nil, fmt.Errorf("decode labels: duplicate label name %q", key)
52			}
53			var value *string
54			if err := dec.Decode(&value); err != nil {
55				return nil, fmt.Errorf("decode labels: value for %q must be a string", key)
56			}
57			if value == nil {
58				return nil, fmt.Errorf("decode labels: value for %q must be a string", key)
59			}
60			labels[key] = *value
61		}
62		if _, err := dec.Token(); err != nil { // closing '}'
63			return nil, fmt.Errorf("decode labels: %w", err)
64		}
