99	// errors, malformed timestamps, malformed labels, and trailing data are
100	// rejected; callers remain responsible for emptiness and field validation.
101	func DecodeBatch(data []byte) ([]Event, error) {
102		dec := json.NewDecoder(bytes.NewReader(data))
103		dec.DisallowUnknownFields()
104		var dtos []rawEventDTO
105		if err := dec.Decode(&dtos); err != nil {
106			return nil, fmt.Errorf("decode events array: %w", err)
107		}
108		var extra json.RawMessage
109		if err := dec.Decode(&extra); err != io.EOF {
110			if err == nil {
111				return nil, fmt.Errorf("decode events array: unexpected trailing data")
112			}
