1	package events
2	
3	import (
4		"fmt"
5		"strings"
6		"unicode/utf8"
7	)
8	
9	// Label limits shared by ingestion and query filters. Names and values are
10	// trimmed of surrounding whitespace, keep their case, and must be non-empty
11	// afterwards; lengths are counted in Unicode code points.
12	const (
13		// MaxLabelsPerEvent caps how many labels a single event may carry.
14		MaxLabelsPerEvent = 32
15		// MaxLabelNameRunes bounds a label name in Unicode code points.
16		MaxLabelNameRunes = 64
17		// MaxLabelValueRunes bounds a label value in Unicode code points.
18		MaxLabelValueRunes = 256
19		// MaxLabelFilters caps how many label conditions one query may carry.
20		MaxLabelFilters = 32
21	)
22	
23	// NormalizeLabels trims and validates a label set. A nil or empty set
24	// normalizes to nil, so the three "no labels" spellings (absent, null, {})
25	// are indistinguishable once stored. Names that differ only in surrounding
26	// whitespace collide and are rejected, as are over-long or empty names and
27	// values.
28	func NormalizeLabels(labels map[string]string) (map[string]string, error) {
29		if len(labels) == 0 {
30			return nil, nil
31		}
32		if len(labels) > MaxLabelsPerEvent {
33			return nil, &ValidationError{Reason: fmt.Sprintf("event must not have more than %d labels", MaxLabelsPerEvent)}
34		}
35		normalized := make(map[string]string, len(labels))
36		for name, value := range labels {
37			name = strings.TrimSpace(name)
38			value = strings.TrimSpace(value)
39			if err := checkLabel(name, value); err != nil {
40				return nil, err
41			}
42			if _, dup := normalized[name]; dup {
43				return nil, &ValidationError{Reason: fmt.Sprintf("label name %q repeats after trimming", name)}
44			}
45			normalized[name] = value
46		}
47		return normalized, nil
48	}
49	
50	// checkLabel enforces the name/value rules every label and every label
51	// filter condition follows.
52	func checkLabel(name, value string) error {
53		if name == "" {
54			return &ValidationError{Reason: "label name must not be empty"}
55		}
56		if value == "" {
57			return &ValidationError{Reason: "label value must not be empty"}
58		}
59		if utf8.RuneCountInString(name) > MaxLabelNameRunes {
60			return &ValidationError{Reason: fmt.Sprintf("label name must not exceed %d characters", MaxLabelNameRunes)}
61		}
62		if utf8.RuneCountInString(value) > MaxLabelValueRunes {
63			return &ValidationError{Reason: fmt.Sprintf("label value must not exceed %d characters", MaxLabelValueRunes)}
64		}
65		return nil
66	}
67	
68	// ParseLabelConditions turns repeated "name=value" query parameters into a
69	// normalized condition set. The first '=' splits name from value; later
70	// equals signs belong to the value. Names and values follow the ingestion
71	// trimming and limit rules, and conditions whose names collide after
72	// trimming are rejected.
73	func ParseLabelConditions(raw []string) (map[string]string, error) {
74		if len(raw) == 0 {
75			return nil, nil
76		}
77		if len(raw) > MaxLabelFilters {
78			return nil, &ValidationError{Reason: fmt.Sprintf("at most %d label filters are allowed", MaxLabelFilters)}
79		}
80		conditions := make(map[string]string, len(raw))
81		for _, item := range raw {
82			name, value, ok := strings.Cut(item, "=")
83			if !ok {
84				return nil, &ValidationError{Reason: "label filter must use the form name=value"}
85			}
86			name = strings.TrimSpace(name)
87			value = strings.TrimSpace(value)
88			if err := checkLabel(name, value); err != nil {
89				return nil, err
90			}
91			if _, dup := conditions[name]; dup {
92				return nil, &ValidationError{Reason: fmt.Sprintf("label filter %q repeats", name)}
93			}
94			conditions[name] = value
95		}
96		return conditions, nil
97	}
98	
99	// labelsMatch reports whether a stored label set satisfies every condition.
100	// An event missing a conditioned label never matches, and comparison is
101	// case-sensitive on both names and values.
102	func labelsMatch(labels, conditions map[string]string) bool {
103		for name, want := range conditions {
104			got, ok := labels[name]
105			if !ok || got != want {
106				return false
107			}
108		}
109		return true
110	}
