			key, ok := tok.(string)
			if !ok {
				return errors.New("invalid JSON object key")
			}
			if _, dup := f.keys[key]; dup {
				return fmt.Errorf("duplicate JSON field %q", key)
			}
			f.keys[key] = struct{}{}
			f.expectKey = false
		} else {
			f.expectKey = true
		}
	}
}

