func TestPreviewRecoveryStreakResetsAtThreshold(t *testing.T) {
	// [3,3,0,3,0,0], recover 2: trigger at w1; w2 low, w3 high restarts the
	// recovery streak; w4/w5 then recover at end of w5.
	tl := previewTimeline(t,
