14		"github.com/cocosolocoder/signalroom/internal/events"
15	)
16	
17	// preview bounds for the integer request fields.
18	const (
19		minPreviewWindowSeconds = 1
20		maxPreviewWindowSeconds = 86400
21		minPreviewThreshold     = 1
22		maxPreviewThreshold     = 1000000
23		minPreviewStreak        = 1
24		maxPreviewStreak        = 100
25		maxPreviewGroupBy       = 4
26	)
27	
28	// previewRequest is the POST /alerts/preview body. All fields except the
29	// filters are required; the strict decoder rejects unknown fields and the
30	// duplicate-key walk rejects repeated JSON fields.
31	type previewRequest struct {
32		Since          time.Time         `json:"since"`
33		Until          time.Time         `json:"until"`
34		WindowSeconds  int               `json:"window_seconds"`
35		Threshold      int               `json:"threshold"`
36		TriggerWindows int               `json:"trigger_windows"`
37		RecoverWindows int               `json:"recover_windows"`
38		Service        string            `json:"service"`
39		Severity       string            `json:"severity"`
40		Labels         map[string]string `json:"labels"`
41		GroupBy        []string          `json:"group_by"`
42	}
43	
44	// previewResponse is the 200 body. Groups carry their per-window boundaries,
45	// counts, and end-of-window states; Alerts lists every alert in trigger-time
46	// order across all groups.
47	type previewResponse struct {
48		Groups []previewGroupDTO `json:"groups"`
49		Alerts []previewAlertDTO `json:"alerts"`
50	}
51	
52	type previewGroupDTO struct {
53		Service string             `json:"service"`
54		Labels  map[string]*string `json:"labels,omitempty"`
55		Windows []previewWindowDTO `json:"windows"`
56	}
57	
58	type previewWindowDTO struct {
59		Since string `json:"since"`
60		Until string `json:"until"`
61		Count int    `json:"count"`
62		State string `json:"state"`
63	}
64	
65	type previewAlertDTO struct {
66		Service     string             `json:"service"`
67		Labels      map[string]*string `json:"labels,omitempty"`
68		TriggeredAt string             `json:"triggered_at"`
69		RecoveredAt *string            `json:"recovered_at"`
70	}
71	
72	func (h *Handler) previewAlerts(w http.ResponseWriter, r *http.Request) {
73		if r.Method != http.MethodPost {
74			w.Header().Set("Allow", "POST")
75			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
76			return
77		}
78		if h.unavailable() {
79			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
80			return
81		}
82	
83		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
84		if err != nil {
85			writeError(w, http.StatusBadRequest, "invalid JSON body")
86			return
87		}
88		if err := rejectDuplicateJSONFields(body); err != nil {
89			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
90			return
91		}
92	
93		dec := json.NewDecoder(bytes.NewReader(body))
94		dec.DisallowUnknownFields()
95		var req previewRequest
96		if err := dec.Decode(&req); err != nil {
97			writeError(w, http.StatusBadRequest, "invalid preview request")
98			return
99		}
100		var extra json.RawMessage
101		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
102			writeError(w, http.StatusBadRequest, "invalid JSON body")
103			return
104		}
105	
106		if err := validatePreviewRequest(req); err != nil {
107			writeError(w, http.StatusBadRequest, err.Error())
108			return
109		}
110	
111		labels, err := events.NormalizeLabels(req.Labels)
112		if err != nil {
113			writeError(w, http.StatusBadRequest, err.Error())
114			return
115		}
116		groupBy, err := normalizePreviewGroupBy(req.GroupBy)
117		if err != nil {
118			writeError(w, http.StatusBadRequest, err.Error())
119			return
120		}
121	
122		query := events.AlertPreviewQuery{
123			Service:        req.Service,
124			Severity:       req.Severity,
125			Labels:         labels,
126			Since:          req.Since,
127			Until:          req.Until,
128			Window:         time.Duration(req.WindowSeconds) * time.Second,
129			Threshold:      req.Threshold,
130			TriggerWindows: req.TriggerWindows,
131			RecoverWindows: req.RecoverWindows,
132			GroupBy:        groupBy,
133		}
134		preview, err := h.timeline.PreviewAlerts(query)
135		if err != nil {
136			switch {
137			case errors.Is(err, events.ErrPreviewTooManyWindows):
138				writeError(w, http.StatusBadRequest, "preview range requires more than 10000 windows")
139			case errors.Is(err, events.ErrPreviewTooManyGroups):
140				writeError(w, http.StatusBadRequest, "preview requires more than 100000 group-window cells")
141			default:
142				writeError(w, http.StatusBadRequest, err.Error())
143			}
144			return
145		}
146	
147		writeJSON(w, http.StatusOK, previewResponseFromResult(preview))
148	}
149	
150	// validatePreviewRequest checks required presence, the range order, and the
151	// integer bounds. Missing timestamps surface as zero instants, which fail the
152	// range check with a specific message.
153	func validatePreviewRequest(req previewRequest) error {
154		if req.Since.IsZero() {
155			return errors.New("since is required and must be an RFC3339Nano timestamp")
156		}
157		if req.Until.IsZero() {
158			return errors.New("until is required and must be an RFC3339Nano timestamp")
159		}
160		if !req.Since.Before(req.Until) {
161			return errors.New("since must be before until")
162		}
163		if req.WindowSeconds < minPreviewWindowSeconds || req.WindowSeconds > maxPreviewWindowSeconds {
164			return errors.New("window_seconds must be an integer from 1 to 86400")
165		}
166		if req.Threshold < minPreviewThreshold || req.Threshold > maxPreviewThreshold {
167			return errors.New("threshold must be an integer from 1 to 1000000")
168		}
169		if req.TriggerWindows < minPreviewStreak || req.TriggerWindows > maxPreviewStreak {
170			return errors.New("trigger_windows must be an integer from 1 to 100")
171		}
172		if req.RecoverWindows < minPreviewStreak || req.RecoverWindows > maxPreviewStreak {
173			return errors.New("recover_windows must be an integer from 1 to 100")
174		}
175		return nil
176	}
177	
178	// normalizePreviewGroupBy trims and validates the group-by label names using
179	// the same name rules as ingestion: non-empty, at most 64 Unicode code points,
180	// and no two names colliding after trimming. At most four names are allowed.
181	func normalizePreviewGroupBy(raw []string) ([]string, error) {
182		if len(raw) > maxPreviewGroupBy {
183			return nil, fmt.Errorf("group_by may contain at most %d label names", maxPreviewGroupBy)
184		}
185		out := make([]string, 0, len(raw))
186		seen := make(map[string]struct{}, len(raw))
187		for _, name := range raw {
188			name = strings.TrimSpace(name)
189			if name == "" {
190				return nil, errors.New("group_by label name must not be empty")
191			}
192			if utf8.RuneCountInString(name) > events.MaxLabelNameRunes {
193				return nil, fmt.Errorf("group_by label name must not exceed %d characters", events.MaxLabelNameRunes)
194			}
195			if _, dup := seen[name]; dup {
196				return nil, fmt.Errorf("group_by label name %q repeats after trimming", name)
197			}
198			seen[name] = struct{}{}
199			out = append(out, name)
200		}
201		return out, nil
202	}
203	
204	// previewResponseFromResult maps the domain result to its wire form, rendering
205	// every instant in UTC with nanosecond precision.
206	func previewResponseFromResult(preview events.AlertPreview) previewResponse {
207		groups := make([]previewGroupDTO, len(preview.Groups))
208		for i, group := range preview.Groups {
209			windows := make([]previewWindowDTO, len(group.Windows))
210			for j, window := range group.Windows {
211				windows[j] = previewWindowDTO{
212					Since: utcRFC3339Nano(window.Since),
213					Until: utcRFC3339Nano(window.Until),
214					Count: window.Count,
215					State: window.State,
216				}
217			}
218			groups[i] = previewGroupDTO{
219				Service: group.Service,
220				Labels:  group.Labels,
221				Windows: windows,
222			}
223		}
224	
225		alerts := make([]previewAlertDTO, len(preview.Alerts))
226		for i, alert := range preview.Alerts {
227			dto := previewAlertDTO{
228				Service:     alert.Service,
229				Labels:      alert.Labels,
230				TriggeredAt: utcRFC3339Nano(alert.TriggeredAt),
231				RecoveredAt: nil,
232			}
233			if alert.RecoveredAt != nil {
234				recovered := utcRFC3339Nano(*alert.RecoveredAt)
235				dto.RecoveredAt = &recovered
236			}
237			alerts[i] = dto
238		}
239		return previewResponse{Groups: groups, Alerts: alerts}
240	}
241	
242	// rejectDuplicateJSONFields walks the JSON document and rejects any object
243	// with a repeated key, including nested label objects. encoding/json silently
244	// overwrites duplicate keys on decode, so the walk is the only guard.
245	func rejectDuplicateJSONFields(data []byte) error {
246		dec := json.NewDecoder(bytes.NewReader(data))
247		type frame struct {
248			object    bool
249			expectKey bool
250			keys      map[string]struct{}
251		}
252		var stack []*frame
253		for {
254			tok, err := dec.Token()
255			if errors.Is(err, io.EOF) {
256				return nil
257			}
258			if err != nil {
259				return err
260			}
261			if delim, ok := tok.(json.Delim); ok {
262				switch delim {
263				case '{':
264					stack = append(stack, &frame{object: true, expectKey: true, keys: map[string]struct{}{}})
265				case '[':
266					stack = append(stack, &frame{object: false})
267				case '}', ']':
268					if len(stack) == 0 {
269						return errors.New("unexpected JSON delimiter")
270					}
271					stack = stack[:len(stack)-1]
272				}
273				continue
274			}
275			if len(stack) == 0 || !stack[len(stack)-1].object {
276				continue
277			}
278			f := stack[len(stack)-1]
279			if f.expectKey {
280				key, ok := tok.(string)
281				if !ok {
282					return errors.New("invalid JSON object key")
283				}
284				if _, dup := f.keys[key]; dup {
285					return fmt.Errorf("duplicate JSON field %q", key)
286				}
287				f.keys[key] = struct{}{}
288				f.expectKey = false
289			} else {
290				f.expectKey = true
291			}
292		}
293	}
